import type {
  InferrableClientTypes,
  Maybe,
  TRPCResultMessage,
  TRPCSuccessResponse,
} from '@trpc/server/unstable-core-do-not-import';
import type { ResponseEsque } from '../internals/types';
import type { TRPCClientError } from '../TRPCClientError';
import type { TRPCConnectionState } from './internals/subscriptions';

export {
  isNonJsonSerializable,
  isFormData,
  isOctetType,
} from './internals/contentTypes';

/**
 * @internal
 */
export interface OperationContext extends Record<string, unknown> {}

/**
 * @internal
 */
export type Operation<TInput = unknown> = {
  id: number;
  type: 'mutation' | 'query' | 'subscription';
  input: TInput;
  path: string;
  context: OperationContext;
  signal: Maybe<AbortSignal>;
};

interface HeadersInitEsque {
  [Symbol.iterator](): IterableIterator<[string, string]>;
}

/**
 * @internal
 */
export type HTTPHeaders =
  | HeadersInitEsque
  | Record<string, string[] | string | undefined>;

/**
 * The default `fetch` implementation has an overloaded signature. By convention this library
 * only uses the overload taking a string and options object.
 */
export type TRPCFetch = (
  url: string,
  options?: RequestInit,
) => Promise<ResponseEsque>;

export interface TRPCClientRuntime {
  // nothing here anymore
}

/**
 * @internal
 */
export interface OperationResultEnvelope<TOutput, TError> {
  result:
    | TRPCResultMessage<TOutput>['result']
    | TRPCSuccessResponse<TOutput>['result']
    | TRPCConnectionState<TError>;
  context?: OperationContext;
}

/**
 * @internal
 */
export type OperationResultObservable<
  TInferrable extends InferrableClientTypes,
  TOutput,
> = Observable<
  OperationResultEnvelope<TOutput, TRPCClientError<TInferrable>>,
  TRPCClientError<TInferrable>
>;

/**
 * @internal
 */
export type OperationResultObserver<
  TInferrable extends InferrableClientTypes,
  TOutput,
> = Observer<
  OperationResultEnvelope<TOutput, TRPCClientError<TInferrable>>,
  TRPCClientError<TInferrable>
>;

/**
 * @internal
 */
export type OperationLink<
  TInferrable extends InferrableClientTypes,
  TInput = unknown,
  TOutput = unknown,
> = (opts: {
  op: Operation<TInput>;
  next: (
    op: Operation<TInput>,
  ) => OperationResultObservable<TInferrable, TOutput>;
}) => OperationResultObservable<TInferrable, TOutput>;

/**
 * @public
 */
export type TRPCLink<TInferrable extends InferrableClientTypes> = (
  opts: TRPCClientRuntime,
) => OperationLink<TInferrable>;

import { EventEmitter, on } from 'node:events';
import { createTRPCClient, localLink, TRPCClientError } from '@trpc/client';
import { initTRPC, TRPCError } from '@trpc/server';
import { z } from 'zod';

test('localLink runs query and mutation procedures in the same process as the client', async () => {
  const createRouter = (opts: { database: string[] }) => {
    const t = initTRPC.create();
    return t.router({
      list: t.procedure.query(() => {
        return [...opts.database];
      }),
      add: t.procedure
        .input(z.object({ item: z.string() }))
        .mutation(({ input }) => {
          opts.database.push(input.item);
          return opts.database.length;
        }),
    });
  };

  const database: string[] = ['initial'];
  const router = createRouter({ database });

  const client = createTRPCClient<typeof router>({
    links: [localLink({ router })],
  });

  expect(await client.list.query()).toEqual(['initial']);
  expect(await client.add.mutate({ item: 'second' })).toBe(2);
  expect(await client.list.query()).toEqual(['initial', 'second']);
  expect(database).toEqual(['initial', 'second']);
});

test('localLink supports createContext and propagates errors as TRPCClientError', async () => {
  const t = initTRPC.context<{ user: string | null }>().create();

  const router = t.router({
    whoami: t.procedure.query(({ ctx }) => {
      if (!ctx.user) {
        throw new TRPCError({
          code: 'UNAUTHORIZED',
          message: 'Not authenticated',
        });
      }
      return `hello ${ctx.user}`;
    }),
  });

  let currentUser: string | null = 'alice';
  const client = createTRPCClient<typeof router>({
    links: [
      localLink({
        router,
        createContext: async () => ({ user: currentUser }),
      }),
    ],
  });

  expect(await client.whoami.query()).toBe('hello alice');

  currentUser = null;
  await expect(client.whoami.query()).rejects.toThrow(TRPCClientError);
  await expect(client.whoami.query()).rejects.toMatchObject({
    message: 'Not authenticated',
  });
});

test('localLink runs subscription procedures in the same process and cleans up on unsubscribe', async () => {
  const ee = new EventEmitter();
  const t = initTRPC.create();

  const router = t.router({
    onMessage: t.procedure
      .input(z.object({ prefix: z.string() }))
      .subscription(async function* (opts) {
        for await (const [msg] of on(ee, 'message', {
          signal: opts.signal,
        })) {
          yield `${opts.input.prefix}: ${String(msg)}`;
        }
      }),
  });

  const client = createTRPCClient<typeof router>({
    links: [localLink({ router })],
  });

  const received: string[] = [];
  const sub = client.onMessage.subscribe(
    { prefix: 'msg' },
    {
      onData(data) {
        received.push(data);
      },
    },
  );

  await vi.waitFor(() => {
    expect(ee.listenerCount('message')).toBe(1);
  });

  ee.emit('message', 'first');
  ee.emit('message', 'second');

  await vi.waitFor(() => {
    expect(received).toEqual(['msg: first', 'msg: second']);
  });

  sub.unsubscribe();

  await vi.waitFor(() => {
    expect(ee.listenerCount('message')).toBe(0);
  });
});

